package com.siam.vault;

import android.app.AlertDialog;
import android.content.*;
import android.graphics.Bitmap;
import android.net.Uri;
import android.os.Bundle;
import android.provider.MediaStore;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import com.siam.vault.database.AppDatabase;
import com.siam.vault.helper.FileHelper;
import com.siam.vault.helper.Ui;
import java.io.File;
import java.util.*;

public class PhotoActivity extends AppCompatActivity {
    private AppDatabase db;private GridLayout grid;private boolean bin;private String album,pendingAlbum="সাধারণ";
    @Override protected void onCreate(Bundle b){super.onCreate(b);Ui.secure(this);db=new AppDatabase(this);bin=getIntent().getBooleanExtra("bin",false);album=getIntent().getStringExtra("album");if(bin){long cutoff=System.currentTimeMillis()-30L*24*60*60*1000;for(AppDatabase.Media m:db.expiredRecycleItems(cutoff)){FileHelper.deleteVaultFile(m);db.remove(m.id);}}render();}
    private void render(){LinearLayout root=Ui.column(this);LinearLayout top=Ui.row(this);TextView back=Ui.chip(this,"Back",this::finish);top.addView(back);TextView title=Ui.text(this,bin?"Recycle Bin":"Photos",24,true);top.addView(title);Ui.add(root,top,-2);if(!bin){Ui.add(root,Ui.button(this,"ছবি Import করুন",this::pick),52);EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Search photos");Ui.add(root,search,48);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){load(s.toString());}public void afterTextChanged(android.text.Editable e){}});}
        grid=new GridLayout(this);grid.setColumnCount(3);ScrollView scroll=new ScrollView(this);scroll.addView(grid);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);load("");}
    private void load(String query){if(grid==null)return;grid.removeAllViews();for(AppDatabase.Media m:db.media("image",bin,album)){if(query!=null&&!m.name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER);card.setPadding(6,6,6,6);card.setBackground(Ui.shape(-1,Ui.dp(this,14),0xFFF1F1F1));ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);Bitmap thumb=FileHelper.thumbnail(this,m);if(thumb!=null)image.setImageBitmap(thumb);else image.setImageResource(android.R.drawable.ic_menu_gallery);card.addView(image,new LinearLayout.LayoutParams(-1,Ui.dp(this,76)));TextView name=Ui.text(this,m.name,11,false);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(name);card.setOnClickListener(v->{if(bin)binActions(m);else preview(m);});card.setOnLongClickListener(v->{actions(m);return true;});GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=Ui.dp(this,118);p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.setMargins(4,4,4,4);grid.addView(card,p);}}
    private void pick(){EditText name=new EditText(this);name.setSingleLine(true);name.setHint("Album-এর নাম");name.setText(album==null?"সাধারণ":album);new AlertDialog.Builder(this).setTitle("Album নির্বাচন করুন").setMessage("নতুন নাম লিখলে সেটি নতুন Album হবে।").setView(name).setNegativeButton("Cancel",null).setPositiveButton("ছবি বাছুন",(d,w)->{pendingAlbum=name.getText().toString().trim();if(pendingAlbum.isEmpty())pendingAlbum="সাধারণ";Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,41);}).show();}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==41&&result==RESULT_OK&&data!=null){List<Uri> items=new ArrayList<>(),imported=new ArrayList<>();if(data.getClipData()!=null){for(int x=0;x<data.getClipData().getItemCount();x++)items.add(data.getClipData().getItemAt(x).getUri());}else if(data.getData()!=null)items.add(data.getData());int ok=0;for(Uri uri:items){try{FileHelper.importUri(this,uri,"image",pendingAlbum);ok++;imported.add(uri);}catch(Exception ignored){}}Toast.makeText(this,ok+"টি ছবি encrypted vault-এ Import হয়েছে",Toast.LENGTH_LONG).show();load("");if(!imported.isEmpty())askDeleteOriginals(imported);}}
    private void askDeleteOriginals(List<Uri> uris){new AlertDialog.Builder(this).setTitle("Gallery থেকে Delete করবেন?").setMessage("Import সফল হয়েছে। নির্বাচিত original ফাইলগুলো মুছতে চাইলে Delete চাপুন; provider অনুমতি না দিলে Gallery থেকে নিজে মুছতে হবে।").setNegativeButton("রেখে দিন",null).setPositiveButton("Delete originals",(d,w)->{int count=0;for(Uri u:uris)try{count+=getContentResolver().delete(u,null,null);}catch(Exception ignored){}Toast.makeText(this,count>0?count+"টি original মুছে গেছে":"এই provider delete করতে দেয়নি — Gallery থেকে নিজে মুছুন",Toast.LENGTH_LONG).show();}).show();}
    private void preview(AppDatabase.Media m){try{ImageView image=new ImageView(this);image.setImageBitmap(FileHelper.previewBitmap(this,m));image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);new AlertDialog.Builder(this).setTitle(m.name).setView(image).setPositiveButton("বন্ধ",null).show();}catch(Exception e){Toast.makeText(this,"ছবি খোলা যায়নি",Toast.LENGTH_SHORT).show();}}
    private void actions(AppDatabase.Media m){String[] opts=bin?new String[]{"Restore to Vault","চিরতরে Delete"}:new String[]{"Gallery-তে ফিরিয়ে দিন","Recycle Bin-এ রাখুন"};new AlertDialog.Builder(this).setTitle(m.name).setItems(opts,(d,w)->{if(bin){if(w==0){db.restore(m.id);load("");}else permanent(m);}else if(w==0)restoreGallery(m);else{db.softDelete(m.id);load("");}}).show();}
    private void binActions(AppDatabase.Media m){actions(m);}
    private void restoreGallery(AppDatabase.Media m){new AlertDialog.Builder(this).setTitle("Gallery-তে ফিরিয়ে দিন?").setMessage("ফাইলটি Gallery-তে কপি হবে। সম্পন্ন হলে Vault-এর কপি মুছে যাবে।").setNegativeButton("না",null).setPositiveButton("Restore",(d,w)->new Thread(()->{try{FileHelper.restoreToGallery(this,m);db.remove(m.id);new File(m.path).delete();runOnUiThread(()->{Toast.makeText(this,"Gallery-তে ফিরেছে",Toast.LENGTH_SHORT).show();load("");});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Restore ব্যর্থ হয়েছে",Toast.LENGTH_LONG).show());}}).start()).show();}
    private void permanent(AppDatabase.Media m){new AlertDialog.Builder(this).setTitle("চিরতরে Delete?").setMessage("এই encrypted file আর ফেরানো যাবে না।").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{FileHelper.deleteVaultFile(m);db.remove(m.id);load("");}).show();}
}
